    if width < 1:
        raise ValueError("width must be at least 1")
    if dwidth(text) <= width:
        return text
    out = []
    used = 0
    for ch in text:
        cw = dwidth(ch)
        if used + cw > width - 1:
            break
        out.append(ch)
        used += cw
    return "".join(out) + "…"

